98	    /**
99	     * Next {@code frustumSize} after traveling {@code stepDistance} blocks through one boundary
100	     * interaction. Growth and shrink are separate:
101	     * <pre>
102	     *   grown = previousSize + growthPerBlock * stepDistance
103	     *   next  = lerp(min: leftoverEnergy², max: 1, t: polarAlignment) * grown
104	     * </pre>
105	     * Pass {@code growthPerBlock = 0} on reflect (no growth). On permeate, pass the nominal rate so
106	     * growth is applied before the energy/alignment shrink coefficient.
107	     *
108	     * <p>{@code polarAlignment} is the raw {@code (rayNorm·polNorm)²} alignment at the boundary just
109	     * resolved (1.0 when the boundary had no polarization vector — a clean, unambiguous interface
110	     * imposes no throttle). {@code leftoverEnergyCoefficient} is whichever of reflectivity/
111	     * transmission actually carried the beam forward through that boundary (only one applies per
112	     * step: the beam either reflected or transmitted); it is squared before blending so shrink grows
113	     * faster than the raw coefficient falls off — a beam that only carries half its energy forward
114	     * loses three-quarters of its footprint headroom, not half. Full alignment leaves the (grown)
115	     * footprint unchanged by energy loss; poor alignment throttles toward the surviving energy
116	     * fraction.
117	     *
118	     * <p>This is the only place {@code frustumSize} advances in the cast process outside of its
119	     * initial value — callers hold the running size on their own state (e.g. {@code Cast.frustumSize})
120	     * and feed it back in as {@code previousSize} each step.
121	     */
122	    public static double nextFrustumSize(
123	            double previousSize,
124	            double stepDistance,
125	            double growthPerBlock,
126	            double polarAlignment,
127	            double leftoverEnergyCoefficient
128	    ) {
129	        double grown = previousSize + growthPerBlock * stepDistance;
130	        double leftoverEnergySquared = leftoverEnergyCoefficient * leftoverEnergyCoefficient;
131	        double blend = leftoverEnergySquared + (1.0 - leftoverEnergySquared) * polarAlignment;
132	        return blend * grown;
133	    }
134	
135	    /**
136	     * LOD step for a footprint width: schedule {@code 1,1,2,2,4,4,8,8,16,16,…} capped at
137	     * {@link #MAX_STEP}. Derived from footprint slots {@code floor(footprint - BASE)}.
138	     */
139	    public static int stepForSize(double footprint) {
140	        if (footprint < BASE_FOOTPRINT) {
141	            return 1;
142	        }
143	        int slot = (int) Math.floor(footprint - BASE_FOOTPRINT);
144	        int shift = Math.min(4, slot / 2);
145	        return 1 << shift;
146	    }
