148	    /**
149	     * LOD step for a traveled {@code distance} under linear (non-compounding) footprint growth:
150	     * schedule {@code 1,1,2,2,4,4,8,8,16,16,…} capped at {@link #MAX_STEP}. Used by contexts that
151	     * only preview footprint growth over free travel (e.g. the debug beam walker) rather than
152	     * tracking real per-interaction {@code frustumSize} state — see {@link #nextFrustumSize} for
153	     * the stateful per-step model used by the live cast.
154	     *
155	     * @param growthPerBlock precomputed rate, e.g. {@code PrecomputedConfig.pConfig.frustumGrowthPerBlock}
156	     */
157	    public static int stepForDistance(double distance, double growthPerBlock) {
158	        return stepForSize(footprintAt(distance, growthPerBlock));
159	    }
