172	    /** Align {@code pos} onto the {@code step}-grid that tiles from {@code leafStart}. */
173	    public static @NotNull BlockPos alignOrigin(@NotNull BlockPos pos, @NotNull BlockPos leafStart, int step) {
174	        int s = Math.max(1, step);
175	        int x = leafStart.getX() + Math.floorDiv(pos.getX() - leafStart.getX(), s) * s;
176	        int y = leafStart.getY() + Math.floorDiv(pos.getY() - leafStart.getY(), s) * s;
177	        int z = leafStart.getZ() + Math.floorDiv(pos.getZ() - leafStart.getZ(), s) * s;
178	        return new BlockPos(x, y, z);
