198	    /**
199	     * Builds the N/E/D map from the first exit plane and the next same-size DDA face the ray would
200	     * strike after crossing it. The second face is pure arithmetic (virtual neighbor cell of
201	     * {@code cellSize}) — no octree fetch. Returns {@code null} when that projected face shares
202	     * {@code firstPlane}'s axis (ordinary non-NED DDA boundary).
203	     *
204	     * @param cellBase   min corner of H
205	     * @param hitPos     position on the first exit face
206	     * @param firstPlane Cast plane ({@code -sign(ray)} on the crossed axis)
207	     */
208	    public static @Nullable ForwardMap forwardMap(
209	            @NotNull Vec3d cellBase,
210	            int cellSize,
211	            @NotNull Vec3d hitPos,
212	            @NotNull Vec3d rayDir,
213	            @NotNull Vec3i firstPlane
214	    ) {
215	        if (firstPlane.equals(Vec3i.ZERO)) {
216	            return null;
217	        }
218	        int s = Math.max(1, cellSize);
219	        int nAxis = faceAxis(firstPlane);
220	        int nSign = travelSign(firstPlane, rayDir, nAxis);
221	        Vec3i secondPlane = nextDdaPlane(cellBase, s, hitPos, rayDir, nAxis, nSign);
222	        if (secondPlane == null || secondPlane.equals(Vec3i.ZERO)) {
223	            return null;
224	        }
225	        int eAxis = faceAxis(secondPlane);
226	        if (eAxis == nAxis) {
227	            return null;
228	        }
229	        int eSign = travelSign(secondPlane, rayDir, eAxis);
230	        if (eSign == 0) {
231	            return null;
232	        }
233	        Vec3i n = axisUnit(nAxis, nSign * s);
234	        Vec3i e = axisUnit(eAxis, eSign * s);
235	        Vec3i d = new Vec3i(n.getX() + e.getX(), n.getY() + e.getY(), n.getZ() + e.getZ());
236	        return new ForwardMap(n, e, d, nAxis, eAxis);
237	    }
