314	    private static int travelSign(@NotNull Vec3i plane, @NotNull Vec3d rayDir, int axis) {
315	        int s = axisSign(component(rayDir, axis));
316	        if (s != 0) {
317	            return s;
318	        }
319	        int f = axis == 0 ? plane.getX() : axis == 1 ? plane.getY() : plane.getZ();
320	        s = -Integer.signum(f);
321	        return s == 0 ? 1 : s;
322	    }
