324	    /**
325	     * Four-map classifier. {@code n}/{@code e}/{@code d} are whether the host→neighbor interaction
326	     * blocks (low permeate — see {@link #blocksPermeation}). Head-on (no {@code E}) is
327	     * {@link Interaction#FACE} when {@code N} blocks, else {@link Interaction#GAP}.
328	     *
329	     * <p>When {@code N} is open, the exit is always {@link Interaction#GAP} — side walls on
330	     * {@code E}/{@code D} must not invent a face reflection through an open exit (that was
331	     * counting matched air:air hosts as R=1).
332	     */
333	    public static @NotNull Interaction classify(boolean nBlocks, boolean eBlocks, boolean dBlocks) {
334	        if (nBlocks && eBlocks && dBlocks) {
335	            return Interaction.CORNER;
336	        }
337	        if (nBlocks && eBlocks) {
338	            return Interaction.SPLIT;
339	        }
340	        if (nBlocks && dBlocks) {
341	            return Interaction.FACE;
342	        }
343	        // N open, or N alone blocks with E/D open: transmit through the exit (GAP).
344	        return Interaction.GAP;
345	    }
