347	    /**
348	     * Host→neighbor interaction permeate: {@code (1 - R(host, neighbor)) * neighborPermeation}.
349	     * Missing/non-finite neighbor impedance → fully open ({@code 1}). Non-finite neighbor
350	     * permeation defaults to {@code 1} so impedance mismatch alone still drives the result.
351	     */
352	    public static double interactionPermeation(double hostZ, double neighborZ, double neighborPermeation) {
353	        if (!Double.isFinite(neighborZ) || !Double.isFinite(hostZ)) {
354	            return 1.0;
355	        }
356	        double r = Acoustics.reflection(hostZ, neighborZ);
357	        double perm = Double.isFinite(neighborPermeation) ? neighborPermeation : 1.0;
358	        return (1.0 - r) * perm;
359	    }
