361	    /**
362	     * Neighbor blocks the forward map when host→neighbor interaction permeate is below
363	     * {@link #PERMEATION_BLOCK_THRESHOLD} (wall-like — reflect/edge-walk rather than phase through).
364	     */
365	    public static final double PERMEATION_BLOCK_THRESHOLD = 0.5;
366	
367	    public static boolean blocksPermeation(double hostZ, double neighborZ, double neighborPermeation) {
368	        return interactionPermeation(hostZ, neighborZ, neighborPermeation) < PERMEATION_BLOCK_THRESHOLD;
369	    }
