1	package dev.thedocruby.resounding.raycast;
2	
3	import org.jetbrains.annotations.NotNull;
4	
5	/**
6	 * Phase 1 tiered beam-subdivision budget (frustums-plan.md Phase 1 task 3, "Resolved": 4 total
7	 * splits per beam, budgeted one split per footprint-size tier — one allowed at frustum size 1,
8	 * another at size 2, a third at size 4, a fourth at size 8; beyond size 8, or once all four tiers
9	 * are spent, no further splitting).
10	 *
11	 * <p>Design decision (not dictated verbatim by the plan): the four size tiers are treated as the
12	 * half-open ranges {@code [1,2)}, {@code [2,4)}, {@code [4,8)}, {@code [8,16)} — i.e. each tier
13	 * covers footprint sizes up to (but not including) the next doubling. A footprint below size 1, or
14	 * at/above size 16, maps to no tier at all ({@link #tierIndexForFootprint} returns {@code -1}),
15	 * consistent with the plan's "beyond size 8 ... no further splitting". This is one reasonable
16	 * reading of an otherwise discrete-sounding "at frustum size 1/2/4/8" description; confirmed
17	 * against {@code BeamBudgetTest} — the half-open interpretation above is what the test suite
18	 * exercises.
19	 */
20	public final class BeamBudget {
21	
22	    /** Number of footprint-size tiers (sizes 1, 2, 4, 8) — see class doc for the resolved cap. */
23	    public static final int TIER_COUNT = 4;
24	
25	    /** Bit {@code i} set means tier {@code i}'s single split has been consumed. */
26	    private final int consumedMask;
27	
28	    private BeamBudget(int consumedMask) {
29	        this.consumedMask = consumedMask;
30	    }
31	
32	    /**
33	     * Fresh budget with all {@value #TIER_COUNT} tiers available (frustums-plan.md Phase 1
34	     * "Resolved: 4 total splits per beam").
35	     */
36	    public static @NotNull BeamBudget full() {
37	        return new BeamBudget(0);
38	    }
39	
40	    /**
41	     * Maps a beam footprint size to its tier index (0..3 for the size-1/2/4/8 tiers), or {@code -1}
42	     * when the footprint falls outside every tier (below size 1, or at/beyond size 16 — see class
43	     * doc).
44	     */
45	    public static int tierIndexForFootprint(double footprintSize) {
46	        if (footprintSize < 1.0) return -1;
47	        if (footprintSize < 2.0) return 0;
48	        if (footprintSize < 4.0) return 1;
49	        if (footprintSize < 8.0) return 2;
50	        if (footprintSize < 16.0) return 3;
51	        return -1;
52	    }
53	
54	    /**
55	     * Whether a split is still available at the tier matching {@code footprintSize}. Always
56	     * {@code false} when {@link #tierIndexForFootprint} would return {@code -1}.
57	     */
58	    public boolean canSplitAt(double footprintSize) {
59	        int tier = tierIndexForFootprint(footprintSize);
60	        if (tier == -1) return false;
61	        return (consumedMask & (1 << tier)) == 0;
62	    }
63	
64	    /**
65	     * Returns a new budget with the tier matching {@code footprintSize} consumed (its single split
66	     * spent). A no-op-equivalent (returns an equal budget) when that tier was already spent or when
67	     * {@code footprintSize} maps to no tier.
68	     */
69	    public @NotNull BeamBudget consumeAt(double footprintSize) {
70	        int tier = tierIndexForFootprint(footprintSize);
71	        if (tier == -1) return this;
72	        return new BeamBudget(consumedMask | (1 << tier));
73	    }
74	
75	    /**
76	     * Count of tiers not yet consumed, {@code 0..}{@value #TIER_COUNT} — this is what feeds
77	     * {@code Physics.notableThreshold}/{@code Physics.isNotableInteraction}'s {@code
78	     * splitsRemaining} parameter (frustums-plan.md Phase 0.5 "Notable-interaction gate ... tied to
79	     * the beam's remaining split budget").
80	     */
81	    public int splitsRemaining() {
82	        return TIER_COUNT - Integer.bitCount(consumedMask);
83	    }
84	}
